INSERT OR IGNORE INTO templates(id,title,description,category,icon,visibility,license,blocks_json,database_json,audience,tags_json,difficulty,setup_minutes,featured,created_at,updated_at) VALUES('public-admin-office-ops','서무 업무 통합관리','주간업무보고 작성, 팀 서무·과 검토, 총괄 취합, 반복 서무 일정과 부서장 질의 근거를 함께 관리하는 공공행정 템플릿입니다.','공공·행정','🗂️','public','00AI Community Template License','{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"서무 업무 통합관리"}]},{"type":"paragraph","content":[{"type":"text","text":"담당자 작성부터 팀 서무 검토, 과 검토, 총괄 취합과 부서장 질의까지 한 공간에서 관리합니다. 실제 운영 전에 기관 조직·마감·내부 규정에 맞게 조정하세요."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"이번 주 운영 정보"}]},{"type":"paragraph","content":[{"type":"text","text":"보고 주차: {{연도}}년 {{주차}}주차 | 담당자 마감: {{일시}} | 팀 검토: {{일시}} | 과 검토: {{일시}} | 총괄 확정: {{일시}}"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"주간업무보고 작성"}]},{"type":"paragraph","content":[{"type":"text","text":"이번 주 주요 추진실적: 업무별 추진 내용, 결과, 실적 수치와 기준일, 근거자료를 기록합니다."}]},{"type":"paragraph","content":[{"type":"text","text":"다음 주 추진계획: 예정일, 협조 부서, 의사결정이 필요한 사항을 기록합니다."}]},{"type":"paragraph","content":[{"type":"text","text":"현안 및 보고사항: 현안, 영향, 대응, 의사결정 요청을 구분합니다."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"검토 흐름"}]},{"type":"paragraph","content":[{"type":"text","text":"담당자 작성·제출 → 팀 서무 형식 검토 → 과 내용 검토 → 총괄 취합·확정. 보완 요청에는 사유·담당자·기한을 남기고 이전 제출 원문과 이력을 보존합니다."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"부서장 질의·근거 답변"}]},{"type":"paragraph","content":[{"type":"text","text":"질문 원문과 관련 주차 보고를 연결하고, 확인된 사실·기준일·출처와 추가 확인 사항을 분리해 기록합니다. 보고자료에서 확인되지 않는 내용은 추정하지 말고 담당 부서 확인이 필요하다고 표시합니다."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"작성 전 확인"}]},{"type":"paragraph","content":[{"type":"text","text":"날짜·요일 일치, 수치·금액 단위와 기준일, 전주 계획과 당주 실적 구분, 개인정보·비공개 내용 최소화, 근거 링크 및 후속 조치 담당자를 확인합니다."}]},{"type":"paragraph","content":[{"type":"text","text":"AI 점검은 오류 후보를 표시하는 보조 기능입니다. 원문에 없는 사실이나 수치를 생성하지 않으며, 담당자가 수정과 답변을 확정합니다. 공식 결재·기록 시스템을 대체하지 않습니다."}]}]}','{"title":"서무 업무·주간보고","view_type":"table","layout_type":"table","statusOptions":["작성 중","팀 서무 검토","과 검토","총괄 검토","보완 요청","확정","완료"],"properties":[{"id":"kind","name":"업무 구분","type":"select","options":["주간보고","인사·복무","예산·회계","기록물·보안","물품·시설","교육·행사","기타"]},{"id":"department","name":"부서","type":"text"},{"id":"owner","name":"담당자","type":"text"},{"id":"stage","name":"검토 단계","type":"select","options":["담당자 작성","팀 서무","과 검토","총괄 취합","부서장 질의"]},{"id":"priority","name":"우선순위","type":"select","options":["긴급","높음","보통","낮음"]},{"id":"due","name":"마감일","type":"date"},{"id":"recurrence","name":"반복 주기","type":"select","options":["없음","매주","매월","분기","반기","매년"]},{"id":"evidence","name":"근거·결과 링크","type":"url"},{"id":"note","name":"검토·보완 의견","type":"text"}],"rows":[{"title":"이번 주 주간업무보고 작성","status":"작성 중","customValues":{"kind":"주간보고","department":"부서명","owner":"담당자","stage":"담당자 작성","priority":"보통","due":"","recurrence":"매주","evidence":"","note":"실적·기준일·근거자료 확인"}},{"title":"주간보고 팀 서무 검토","status":"팀 서무 검토","customValues":{"kind":"주간보고","department":"부서명","owner":"팀 서무","stage":"팀 서무","priority":"높음","due":"","recurrence":"매주","evidence":"","note":"누락·표기·수치 불일치 후보 확인"}},{"title":"부서장 질의 답변 근거 확인","status":"과 검토","customValues":{"kind":"주간보고","department":"부서명","owner":"확인 담당자","stage":"부서장 질의","priority":"보통","due":"","recurrence":"없음","evidence":"","note":"보고 원문과 출처 연결, 미확인 사실 표시"}}],"views":[{"name":"전체 서무 업무","view_type":"table","status_filter":"전체","sort_by_field":"manual","sort_by_2":"none","group_by_field":"none","due_filter":"all","search_query":"","priority_filter":"all","row_open_mode":"side","visible_properties":[]},{"name":"검토 흐름","view_type":"board","status_filter":"전체","sort_by_field":"manual","sort_by_2":"none","group_by_field":"status","due_filter":"all","search_query":"","priority_filter":"all","row_open_mode":"side","visible_properties":[]},